// Parse a Grafana alerting webhook payload into flat fields.
// Grafana's default webhook shape: { receiver, status, alerts: [ { status, labels, annotations, startsAt, endsAt, generatorURL, fingerprint } ], externalURL, commonAnnotations, commonLabels }
const body = $json.body || $json;
const alert = (body.alerts && body.alerts[0]) || body;
const labels = alert.labels || {};
const annotations = alert.annotations || {};

return [{
  json: {
    alertname: labels.alertname || 'unknown_alert',
    severity: labels.severity || 'unknown',
    service: labels.service || labels.job || 'unknown_service',
    summary: annotations.summary || body.commonAnnotations?.summary || 'No summary provided',
    status: alert.status || body.status || 'firing',
    dashboardURL: alert.generatorURL || body.externalURL || '',
    fingerprint: alert.fingerprint || ((labels.alertname || 'unknown') + '-' + (labels.service || labels.job || 'unknown'))
  }
}];

// Flap detection: count how many times this exact alert (by fingerprint)
// has fired in the last 10 minutes, using workflow static data as memory.
const staticData = $getWorkflowStaticData('node');
const key = $json.fingerprint;
const now = Date.now();
const windowMs = 10 * 60 * 1000; // 10 minutes

if (!staticData.fireLog) staticData.fireLog = {};
if (!staticData.fireLog[key]) staticData.fireLog[key] = [];

staticData.fireLog[key] = staticData.fireLog[key].filter((ts) => now - ts < windowMs);
staticData.fireLog[key].push(now);

const recentCount = staticData.fireLog[key].length;

return [{
  json: {
    ...$json,
    recent_fire_count: recentCount
  }
}];

// Parse the AI node's reply into flat fields and merge with the alert.
const item = $input.first().json;
const alert = $('Flap Check').first().json;

let raw = '';
if (Array.isArray(item.content) && item.content[0] && item.content[0].text) {
  raw = item.content[0].text;
} else if (typeof item.content === 'string') {
  raw = item.content;
} else if (item.text) {
  raw = item.text;
} else if (item.message && Array.isArray(item.message.content) && item.message.content[0]) {
  raw = item.message.content[0].text || '';
}

raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    decision: 'real',
    reason: '[PARSE ERROR] Could not parse AI response as JSON: ' + String(raw).slice(0, 200)
  };
}

return [{
  json: {
    ...alert,
    decision: parsed.decision || 'real',
    reason: parsed.reason || '[MISSING] reason'
  }
}];
